"""Dependency-free sanity checks for the DiaBeates Supabase migration."""

from pathlib import Path
import sys


ROOT = Path(__file__).resolve().parents[1]
MIGRATION = ROOT / "supabase" / "migrations" / "20261104004500_create_diabeates_schema.sql"
PASSWORD_RESET_MIGRATION = ROOT / "supabase" / "migrations" / "20261104011000_create_password_reset_tokens.sql"

REQUIRED_TABLES = (
    "users",
    "assessments",
    "risk_results",
    "lab_assessments",
    "feedback",
    "audit_log",
)

PASSWORD_RESET_TABLE = "password_reset_tokens"

REQUIRED_MARKERS = (
    "generated by default as identity",
    "timestamptz",
    "double precision",
    "enable row level security",
    "revoke all on table",
    "from anon, authenticated",
)


def main() -> int:
    if not MIGRATION.is_file():
        print(f"Missing migration: {MIGRATION}", file=sys.stderr)
        return 1
    if not PASSWORD_RESET_MIGRATION.is_file():
        print(f"Missing migration: {PASSWORD_RESET_MIGRATION}", file=sys.stderr)
        return 1

    sql = MIGRATION.read_text(encoding="utf-8").lower()
    password_reset_sql = PASSWORD_RESET_MIGRATION.read_text(encoding="utf-8").lower()
    missing_tables = [
        table for table in REQUIRED_TABLES
        if f"create table if not exists public.{table}" not in sql
    ]
    missing_markers = [marker for marker in REQUIRED_MARKERS if marker not in sql]

    if missing_tables or missing_markers:
        if missing_tables:
            print("Missing tables: " + ", ".join(missing_tables), file=sys.stderr)
        if missing_markers:
            print("Missing SQL markers: " + ", ".join(missing_markers), file=sys.stderr)
        return 1

    if f"create table if not exists public.{PASSWORD_RESET_TABLE}" not in password_reset_sql:
        print(f"Missing table: {PASSWORD_RESET_TABLE}", file=sys.stderr)
        return 1

    print("Supabase migration sanity checks: PASS")
    print(f"Tables checked: {len(REQUIRED_TABLES) + 1}")
    print("RLS and anon/authenticated revocation markers: present")
    print("password_reset_tokens: schema present, data intentionally excluded")
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
